function lang(){let raw=w._pgI18n&&typeof w._pgI18n.curLang==='function'?w._pgI18n.curLang():d.documentElement.lang||'EN';let l=String(raw).toUpperCase().replace(/-/g,'_');if(/^(ZH_HANT|ZH_HK)$/.test(l))l='ZH_TW';if(/^(ZH_HANS|ZH_CN)$/.test(l))l='ZH';return locales[l]?l:locales[l.split('_')[0]]?l.split('_')[0]:'EN';}
const badgeCopy={"EN":["Coming Soon","Magic Studio is coming soon as a Pro feature. Once released, it will be available with an eligible 3-day Pro trial or an active Pro subscription."],"ES":["Próximamente","Magic Studio llegará próximamente como función Pro. Una vez disponible, podrás usarla con una prueba Pro de 3 días si cumples los requisitos o con una suscripción Pro activa."],"FR":["Bientôt disponible","Magic Studio sera bientôt disponible en tant que fonctionnalité Pro. Après son lancement, vous pourrez l’utiliser avec un essai Pro de 3 jours sous réserve d’éligibilité ou un abonnement Pro actif."],"DE":["Demnächst verfügbar","Magic Studio erscheint demnächst als Pro-Funktion. Nach der Veröffentlichung ist es mit einer berechtigten 3-tägigen Pro-Testphase oder einem aktiven Pro-Abonnement verfügbar."],"IT":["Prossimamente","Magic Studio arriverà come funzione Pro. Dopo il lancio sarà disponibile con la prova Pro di 3 giorni per gli utenti idonei o con un abbonamento Pro attivo."],"PT":["Em breve","Magic Studio chegará em breve como recurso Pro. Após o lançamento, estará disponível com o teste Pro de 3 dias para usuários elegíveis ou uma assinatura Pro ativa."],"NL":["Binnenkort beschikbaar","Magic Studio komt binnenkort als Pro-functie. Na de release is het beschikbaar met een Pro-proefperiode van 3 dagen voor wie in aanmerking komt of een actief Pro-abonnement."],"RU":["Скоро","Magic Studio скоро появится как функция Pro. После выхода она будет доступна в рамках 3-дневного пробного периода Pro для имеющих на него право или с активной подпиской Pro."],"ZH":["即将推出","Magic Studio 即将作为 Pro 功能推出。上线后，符合条件的用户可通过 3 天 Pro 试用或有效的 Pro 订阅使用。"],"ZH_TW":["即將推出","Magic Studio 即將作為 Pro 功能推出。上線後，符合資格的使用者可透過 3 天 Pro 試用或有效的 Pro 訂閱使用。"],"JA":["近日公開","Magic Studio は近日公開予定の Pro 機能です。公開後は対象の方の3日間の Pro 体験、または有効な Pro サブスクリプションで利用できます。"],"KO":["출시 예정","Magic Studio는 곧 출시될 Pro 기능입니다. 출시 후에는 자격을 충족하는 사용자의 3일 Pro 체험 또는 활성 Pro 구독을 통해 이용할 수 있습니다."],"AR":["قريبًا","ستتوفر Magic Studio قريبًا كميزة Pro. بعد إطلاقها، ستتاح خلال فترة Pro التجريبية لمدة 3 أيام للمؤهلين أو مع اشتراك Pro نشط."],"HI":["जल्द आ रहा है","Magic Studio जल्द ही Pro सुविधा के रूप में आएगा। रिलीज़ के बाद यह पात्र उपयोगकर्ताओं के 3 दिन के Pro ट्रायल या सक्रिय Pro सदस्यता के साथ उपलब्ध होगा।"],"BN":["শীঘ্রই আসছে","Magic Studio শীঘ্রই Pro বৈশিষ্ট্য হিসেবে আসছে। প্রকাশের পর যোগ্য ব্যবহারকারীদের ৩ দিনের Pro ট্রায়াল বা সক্রিয় Pro সাবস্ক্রিপশনে এটি ব্যবহার করা যাবে।"],"TR":["Yakında","Magic Studio yakında bir Pro özelliği olarak sunulacak. Yayınlandıktan sonra uygun kullanıcıların 3 günlük Pro denemesiyle veya etkin bir Pro aboneliğiyle kullanılabilecek."],"PL":["Już wkrótce","Magic Studio wkrótce pojawi się jako funkcja Pro. Po premierze będzie dostępna w ramach 3-dniowego okresu próbnego Pro dla uprawnionych użytkowników lub aktywnej subskrypcji Pro."],"SV":["Kommer snart","Magic Studio kommer snart som en Pro-funktion. Efter lanseringen blir den tillgänglig med en tre dagars Pro-provperiod för berättigade användare eller en aktiv Pro-prenumeration."],"NO":["Kommer snart","Magic Studio kommer snart som en Pro-funksjon. Etter lansering blir den tilgjengelig med en 3-dagers Pro-prøveperiode for kvalifiserte brukere eller et aktivt Pro-abonnement."],"DA":["Kommer snart","Magic Studio kommer snart som en Pro-funktion. Efter lanceringen bliver den tilgængelig med en 3-dages Pro-prøveperiode for kvalificerede brugere eller et aktivt Pro-abonnement."],"FI":["Tulossa pian","Magic Studio julkaistaan pian Pro-ominaisuutena. Julkaisun jälkeen se on käytettävissä kolmen päivän Pro-kokeilulla siihen oikeutetuille tai aktiivisella Pro-tilauksella."],"EL":["Σύντομα διαθέσιμο","Το Magic Studio θα κυκλοφορήσει σύντομα ως λειτουργία Pro. Μετά την κυκλοφορία θα είναι διαθέσιμο με δοκιμή Pro 3 ημερών για επιλέξιμους χρήστες ή ενεργή συνδρομή Pro."],"HE":["בקרוב","Magic Studio תושק בקרוב כתכונת Pro. לאחר ההשקה היא תהיה זמינה בתקופת ניסיון של 3 ימים למשתמשים זכאים או עם מנוי Pro פעיל."],"ID":["Segera hadir","Magic Studio akan segera hadir sebagai fitur Pro. Setelah dirilis, fitur ini tersedia melalui uji coba Pro 3 hari bagi pengguna yang memenuhi syarat atau langganan Pro aktif."],"MS":["Akan datang","Magic Studio akan hadir tidak lama lagi sebagai ciri Pro. Selepas dilancarkan, ciri ini tersedia dengan percubaan Pro 3 hari bagi pengguna yang layak atau langganan Pro aktif."],"TH":["เร็ว ๆ นี้","Magic Studio จะเปิดตัวเร็ว ๆ นี้ในฐานะฟีเจอร์ Pro หลังเปิดตัว ผู้มีสิทธิ์จะใช้งานได้ผ่านช่วงทดลองใช้ Pro 3 วัน หรือการสมัครสมาชิก Pro ที่ยังใช้งานอยู่"],"VI":["Sắp ra mắt","Magic Studio sẽ sớm ra mắt dưới dạng tính năng Pro. Sau khi phát hành, tính năng này sẽ khả dụng với 3 ngày dùng thử Pro nếu đủ điều kiện hoặc gói đăng ký Pro đang hoạt động."],"UK":["Незабаром","Magic Studio незабаром з’явиться як функція Pro. Після випуску вона буде доступна в межах 3-денного пробного періоду Pro для тих, хто має на нього право, або з активною підпискою Pro."],"CS":["Již brzy","Magic Studio bude brzy dostupné jako funkce Pro. Po vydání bude k dispozici s 3denním zkušebním obdobím Pro pro oprávněné uživatele nebo s aktivním předplatným Pro."],"RO":["În curând","Magic Studio va fi lansat în curând ca funcție Pro. După lansare, va fi disponibil cu perioada de probă Pro de 3 zile pentru utilizatorii eligibili sau cu un abonament Pro activ."],"HU":["Hamarosan","A Magic Studio hamarosan Pro-funkcióként érkezik. A megjelenés után a jogosult felhasználók 3 napos Pro-próbaidőszakával vagy aktív Pro-előfizetéssel lesz elérhető."],"SK":["Už čoskoro","Magic Studio čoskoro príde ako funkcia Pro. Po vydaní bude dostupná s 3-dňovým skúšobným obdobím Pro pre oprávnených používateľov alebo s aktívnym predplatným Pro."],"HR":["Uskoro","Magic Studio uskoro stiže kao značajka Pro. Nakon objave bit će dostupna uz 3-dnevno probno razdoblje Pro za korisnike koji ispunjavaju uvjete ili uz aktivnu pretplatu Pro."],"CA":["Properament","Magic Studio arribarà aviat com a funció Pro. Després del llançament, estarà disponible amb la prova Pro de 3 dies per a usuaris que compleixin els requisits o amb una subscripció Pro activa."],"AF":["Binnekort","Magic Studio kom binnekort as ’n Pro-funksie. Ná bekendstelling sal dit beskikbaar wees met die 3-dae Pro-proeftydperk vir kwalifiserende gebruikers of ’n aktiewe Pro-intekening."],"SW":["Inakuja hivi karibuni","Magic Studio itakuja hivi karibuni kama kipengele cha Pro. Baada ya kuzinduliwa, kitapatikana kwa majaribio ya Pro ya siku 3 kwa wanaostahiki au usajili hai wa Pro."],"HA":["Na zuwa nan ba da jimawa ba","Magic Studio zai zo nan ba da jimawa ba a matsayin fasalin Pro. Bayan ƙaddamarwa, za a iya amfani da shi ta gwajin Pro na kwanaki 3 ga masu cancanta ko biyan kuɗin Pro mai aiki."],"AM":["በቅርቡ ይመጣል","Magic Studio በቅርቡ እንደ Pro ባህሪ ይመጣል። ከተለቀቀ በኋላ ብቁ ለሆኑ ተጠቃሚዎች በ3 ቀን የPro ሙከራ ወይም በንቁ የPro ምዝገባ ይገኛል።"]};
